import{_ as o,l as r,o as e,c as s,v as t,p as E,x as l,d as n,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"掩模坯与 LTEM 基板","description":"","frontmatter":{"title":"掩模坯与 LTEM 基板","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-blank-ltem.md","filePath":"litho/mask-blank-ltem.md","lastUpdated":1789023840000}'),p={name:"litho/mask-blank-ltem.md"};function m(c,a,T,_,A,M){const i=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="掩模坯与-ltem-基板" tabindex="-1">掩模坯与 LTEM 基板 <a class="header-anchor" href="#掩模坯与-ltem-基板" aria-label="Permalink to &quot;掩模坯与 LTEM 基板&quot;">​</a></h1><div class="epigraph"><p>写在膨胀的玻璃上，格子会在剂量里漂；低热胀基板把写入热与扫描热从配准预算里抠掉一截。</p><footer>—— 对照 LTEM（低热膨胀材料）掩模基板与 SEMI 外形/坯料通称；EUV 坯见 SEMI P37 一类规范</footer></div><p><a href="/litho/mask-registration">上一课</a>把放置误差收进套刻。缺口是误差有一截来自基板：石英热胀、平坦度、缺陷。本课钉掩模坯与 LTEM。铬与 MoSi 膜长在什么表面上，留给[下一课](/litho/chrome-mosi-films）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/six-inch-reticle">6 寸外形</a> 规定边长与厚度家族；本课补材料。DUV 透射版用合成石英；对热与配准更严的层用 Ti 掺杂石英一类 LTEM（low thermal expansion material），把热膨胀系数压到普通石英之下。EUV 反射坯是低胀玻璃 + Mo/Si 多层 + 覆盖层 + 吸收体，空白片缺陷规格按 SEMI P37 一类文件走——本课不抄条款毫米数，只钉：坯是光学元件，不是「一块玻璃」。</p><p>缺口是<strong>基板合同</strong>，不是再讲写栅。把 CDU 超差全写成 PEC，会漏掉坯的厚度均匀与应力在夹持后面形变。</p><h3 id="空白片缺陷是掩模良率的起点" tabindex="-1">空白片缺陷是掩模良率的起点 <a class="header-anchor" href="#空白片缺陷是掩模良率的起点" aria-label="Permalink to &quot;空白片缺陷是掩模良率的起点&quot;">​</a></h3><p>多层膜或铬下的坑、颗粒、相缺陷，写完图形也修不回完整布拉格反射。EUV 光化空白检验存在，正是因为非光化检测会漏掉打印缺陷。后课检验针对图形；本课先承认：坏坯不该进入写入队列。</p><p><span class="marginnote">LTEM 改善的是热致配准，不是折射率均匀到可以当透镜用。扫描机物镜是另一套玻璃。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>来料：平坦度、面形、热胀、缺陷图、膜厚（若已镀）。夹持状态要与扫描机和配准仪尽量一致，否则计量与使用是两张面形。EUV 背面导电层与静电吸盘是夹持的一部分，颗粒在背面会局部顶起——见 EUV 掩模台课，本课只把它标成坯的使用约束。</p><p>与写入热：电流越大、时间越短，热梯度越陡，LTEM 的价值越大；普通石英可能把配准墙提前。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>热膨胀把格子作径向或非均匀放大。扫描机可以补偿均匀放大，补偿不了写束扫描路径造成的瞬时非均匀温度场。LTEM 减小系数，等于减小这份瞬态。平坦度误差在投影里变成焦面与畸变项，与镜头像差不同源，却进同一张套刻/焦点图。</p>',14)),(e(),E(d,null,{default:l(()=>[h(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E7%9F%B3%E8%8B%B1%20%2F%20LTEM%22%5D%20--%3E%20FILM%5B%22%E9%95%80%E8%86%9C%3A%20%E9%93%AC%20MoSi%20%E6%88%96%20EUV%20%E5%A4%9A%E5%B1%82%22%5D%0A%20%20FILM%20--%3E%20BLANK%5B%22%E7%A9%BA%E7%99%BD%E7%89%87%E8%A7%84%E6%A0%BC%22%5D%0A%20%20BLANK%20--%3E%20WRITE%5B%22%E5%86%99%E5%85%A5%20%2B%20%E5%A4%B9%E6%8C%81%E9%9D%A2%E5%BD%A2%22%5D%0A%20%20WRITE%20--%3E%20REG%5B%22%E9%85%8D%E5%87%86%20%2F%20%E7%84%A6%E9%9D%A2%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不点名某品牌玻璃的 ppm/K 当作唯一真值。不把 EUV 多层周期误差写成 LTEM 的锅——那是镀膜。坯成本与交期会进最后的 <a href="/litho/mask-cost-cycle">掩模成本</a>，本课不报价。</p><p>后课默认：基板是低胀、已规格化的坯；下一课在它上面长吸收体或相移膜。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LTEM 压热胀，服务写入与扫描时的配准；外形仍是 6 寸家族。</li><li>EUV 坯是多层光学元件，空白缺陷必须光化视角检验。</li><li>夹持状态是计量的一部分。</li><li>出处：LTEM 掩模基板通称；SEMI 外形与 EUV 坯（P37 一类）规范结构。</li></ul>',5))])}const B=o(p,[["render",m]]);export{u as __pageData,B as default};
